Kembalikan jawaban langsung (non-streaming, model auto) fetch('https://puruboy-api.vercel.app/api/chat/completions', {     method: 'POST',     headers: { 'Content-Type': 'application/json' },     body: JSON.stringify({         model: 'auto',         messages: [{ role: 'user', content: 'Halo, apa itu Next.js?' }]     }) }).then(res => res.json()).then(console.log);

Streaming SSE fetch('https://puruboy-api.vercel.app/api/chat/completions', {     method: 'POST',     headers: { 'Content-Type': 'application/json' },     body: JSON.stringify({         model: 'auto',         stream: true,         messages: [             { role: 'system', content: 'Jawab singkat.' },             { role: 'user', content: 'Jelaskan fotosintesis' }         ]     }) }).then(res => {     const reader = res.body.getReader();     const dec = new TextDecoder();     (async () => {         while (true) {             const { done, value } = await reader.read();             if (done) break;             console.log(dec.decode(value));         }     })(); });

Function calling (tools) — balasan berisi message.tool_calls fetch('https://puruboy-api.vercel.app/api/chat/completions', {     method: 'POST',     headers: { 'Content-Type': 'application/json' },     body: JSON.stringify({         model: 'auto',         messages: [{ role: 'user', content: 'Bagaimana cuaca di Jakarta?' }],         tools: [{             type: 'function',             function: {                 name: 'getWeather',                 description: 'Cuaca sebuah kota',                 parameters: { type:'object', properties:{ city:{type:'string'} }, required:['city'] }             }         }]     }) }).then(res => res.json()).then(console.log);

Reasoning non-streaming fetch('https://puruboy-api.vercel.app/api/deepseek/reasoning', {     method: 'POST',     headers: { 'Content-Type': 'application/json' },     body: JSON.stringify({ userID: 'TOKEN_ANDA', prompt: 'Jika sebuah kereta 120 m membutuhkan 12 detik untuk melewati tiang, berapa kecepatannya?' }) }).then(res => res.json()).then(r => console.log(r.reasoning, '=>', r.content));

Streaming SSE fetch('https://puruboy-api.vercel.app/api/deepseek/reasoning', {     method: 'POST',     headers: { 'Content-Type': 'application/json' },     body: JSON.stringify({ userID: 'TOKEN_ANDA', prompt: 'Tebak angka 1-10 yang saya pikirkan', stream: true }) }).then(res => res.text()).then(console.log);

Lanjutkan percakapan (chatID + parentID dari respons sebelumnya) fetch('https://puruboy-api.vercel.app/api/deepseek/reasoning', {     method: 'POST',     headers: { 'Content-Type': 'application/json' },     body: JSON.stringify({ userID: 'TOKEN_ANDA', chatID: 'CHAT_ID_DARI_RESPONS', parentID: 2, prompt: 'Yakin dengan jawabanmu?' }) }).then(res => res.json()).then(console.log);
